#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 14f: Settings in the admin dashboard
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check it, then fast forward main.
#
# After this part, Settings in the dashboard is live (nothing says Soon):
#   Admins
#   * every admin, with you and the founder (ADMIN_EMAIL) marked
#   * invite an admin by email: a link that works once, for 48 hours; they
#     choose their own password and add their own authenticator app
#   * cancel an invitation; remove an admin (signed out everywhere, emailed);
#     the founder cannot be removed, nor can you remove yourself
#   * inviting and removing need a code from your authenticator app or a
#     recovery code
#   Your account
#   * change your password (needs the current one; other sessions end)
#   * move to a new authenticator app (needs your password and a code from
#     the new app; the old one works until then)
#   * new recovery codes (needs your password; the old ones stop working)
#   * wrong answers count toward the lock like failed sign ins
#   Limits (read only)
#   * every request limit with the values the server is using, the usage
#     caps with the Render setting for each, and the dashboard's own rules
#   * every change is in the audit log, with an email notice
#
#   BACKEND    1 new file, 6 changed. No migration
#   DASHBOARD  3 new files, 3 changed. No packages
#
#   ./vm_admin_settings.sh            apply (needs Part 14e on the branch)
#   ./vm_admin_settings.sh --force    apply even if local files differ from GitHub
#   ./vm_admin_settings.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_admin_settings"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_admin_settings_backups"

ADD=(
  "backend/src/lib/adminSettings.ts"
  "dashboard/src/components/AccountParts.tsx"
  "dashboard/src/app/invite/page.tsx"
  "dashboard/src/app/(admin)/settings/page.tsx"
)
MOD=(
  "backend/src/routes/admin.ts"
  "backend/src/lib/admin.ts"
  "backend/src/lib/guard.ts"
  "backend/src/lib/views.ts"
  "backend/src/routes/youtube.ts"
  "backend/src/lib/adminOps.ts"
  "dashboard/src/lib/api.ts"
  "dashboard/src/lib/actions.ts"
  "dashboard/src/components/Shell.tsx"
)
PRE_MOD=(
  "8f0d94eafc93b19c7e728203a8f8b836b62e6357f66c66fae77548c664247163"
  "2a624020c419e4bdcc6e9aa3541a691352d6b070823d31ee3c8821205bc386ea"
