verify "$TMPD/a3" "${NEW_ADD[3]}" "dashboard/src/app/(admin)/settings/page.tsx"

grep -q "$MARKER" "$TMPD/a0"                                   || die "adminSettings.ts payload missing marker. Aborting."
grep -q 'export function limitsOverview' "$TMPD/a0"              || die "adminSettings.ts payload is wrong. Aborting."
grep -q 'export function RecoveryCodes' "$TMPD/a1"               || die "AccountParts.tsx payload is wrong. Aborting."
grep -q 'Join the dashboard' "$TMPD/a2"                          || die "invite page payload is wrong. Aborting."
grep -q 'Use a new authenticator app' "$TMPD/a3"                 || die "settings page payload is wrong. Aborting."
grep -q 'adminSettings' "$TMPD/m0"                   || die "routes/admin.ts payload is wrong. Aborting."
grep -q 'adminInsights' "$TMPD/m0"                   || die "routes/admin.ts payload lost 14e. Aborting."
grep -q 'export async function inviteAdmin' "$TMPD/m1"  || die "lib/admin.ts payload is wrong. Aborting."
grep -q 'export async function resetPassword' "$TMPD/m1" || die "lib/admin.ts payload lost 14a. Aborting."
grep -q 'export const limitRules' "$TMPD/m2"            || die "guard.ts payload is wrong. Aborting."
grep -q 'recordLimitHit' "$TMPD/m2"                     || die "guard.ts payload lost 14d. Aborting."
grep -q 'export const perCallerDay' "$TMPD/m3"          || die "views.ts payload is wrong. Aborting."
grep -q 'export const perWallet' "$TMPD/m4"        || die "youtube.ts payload is wrong. Aborting."
grep -q 'password_changed' "$TMPD/m5"                || die "adminOps.ts payload is wrong. Aborting."
grep -q 'export const getLimits' "$TMPD/m6"             || die "dashboard api.ts payload is wrong. Aborting."
grep -q 'export const getCosts' "$TMPD/m6"              || die "dashboard api.ts payload lost 14e. Aborting."
grep -q 'admin_invited' "$TMPD/m7"                  || die "actions.ts payload is wrong. Aborting."
grep -q 'href: "/settings"' "$TMPD/m8"        || die "Shell.tsx payload is wrong. Aborting."
say "13 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Settings (Part 14f)."
say "No migration and nothing to install."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit && npm run build) && (cd frontend && npx tsc --noEmit && npm run build)"
say "  (cd dashboard && npm install && npx tsc --noEmit && npm run build)"
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_admin_settings.sh --revert"
